    ('greenway:1:entry:EB', 'greenway', '1', 'entry', 'EB', 'Exit 1 - US 15/SR 7 (Leesburg Bypass)', oracle.ST_SetSRID(oracle.ST_MakePoint(-77.5652813, 39.1000972), 4326)::oracle.geography, ARRAY[]::text[], '{"alternative_ranking":{"corridor_position":0},"coordinate_quality":"approximate_interchange","coordinate_source":{"evidence_url":"https://www.dullesgreenway.com/toll-calculator/","method":"reviewed_interchange_projected_to_route_centerline","provider":"Virginia Department of Transportation","retrieved_at":"2026-08-17","source_feature_id":5707,"source_feature_name":"R-VA   SR00267EB","source_url":"https://services.arcgis.com/p5v98VHDX9Atv3l7/arcgis/rest/services/LRS_Route_Master/FeatureServer/0"},"source_context":{"notes":"2-axle E-ZPass rates only; pay-by-plate/3+ axle out of scope. Flat fare per trip, never summed across plazas -- \"the Greenway does not offer a discount for partial usage.\" A trip crossing the mainline plaza (between Exit 8 and Exit 9/Rte 28) pays the mainline rate; a trip confined to Exits 1-8 pays the lower secondary rate. Every mainline crossing also incurs a separate $2.00 Dulles Toll Road charge. Peak hours (6:30-9:00am EB, 4:00-6:30pm WB) are assumed weekday-only -- \"rush hour\" framing and industry convention support this, but no source explicitly excluded weekends; verify before relying on this for a weekend trip. Ramp direction availability is fixed; only the toll rate period depends on time. Battlefield Parkway is bidirectional; Compass Creek is a westbound exit only with no entrance.","retrieved_at":"2026-08-04","source_url":"https://www.dullesgreenway.com/toll-calculator/"},"source_file":"dulles_greenway.json","source_node":{"entry_in":["EB","WB"],"exit_in":["EB","WB"],"label":"Exit 1 - US 15/SR 7 (Leesburg Bypass)"}}'::jsonb),
