    ('source:dtr:EB:10:11', 'dtr:10:entry:EB', 'dtr:11:exit:EB', 'within_facility', NULL, 'EB:10:11', '{"source_context":{"notes":"2-axle E-ZPass rates only; pay-by-plate/3+ axle out of scope. Mainline toll ($4.00) crosses between Exit 16 and Exit 17; ramp toll ($2.00) applies per tolled interchange used, additive with the mainline toll -- two independently confirmed sources agree on a $6.00 total for a typical mainline-crossing single-ramp trip. Exit 16''s ramp toll applies to the eastbound exit only (quoted from source); the westbound movement there is free. No time-of-day variation on this facility. The I-66 / Dulles Toll Road junction is a virtual, bidirectional routing boundary confirmed by the user, not a toll collection point.","retrieved_at":"2026-07-26","source_url":"https://www.dullestollroad.com/toll-rates-electronic-payment-and-pay-plate"},"source_file":"dulles_toll_road.json","source_pair":{"charges":[{"label":"Entrance ramp at Exit 10 - SR 657","price_off_peak_usd":"2.00","price_peak_usd":"2.00"},{"label":"Exit ramp at Exit 11 - SR 286 (Fairfax County Pkwy)","price_off_peak_usd":"2.00","price_peak_usd":"2.00"}],"direction":"EB","entry":"10","exit":"11"}}'::jsonb),
